import{_ as n,l as i,o as a,c as l,v as t,p as s,x as o,d as c,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"指数贴现与时间一致","description":"","frontmatter":{"title":"指数贴现与时间一致","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/exponential-discounting.md","filePath":"econ/exponential-discounting.md","lastUpdated":1789023840000}'),p={name:"econ/exponential-discounting.md"};function _(u,e,h,m,B,A){const r=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="指数贴现与时间一致" tabindex="-1">指数贴现与时间一致 <a class="header-anchor" href="#指数贴现与时间一致" aria-label="Permalink to &quot;指数贴现与时间一致&quot;">​</a></h1><div class="epigraph"><p>把各期效用乘上几何级数再加总，今天的最优计划到了明天仍然最优——这不是心理学发现，是使动态规划可递推的约定。</p><footer>—— Samuelson, A Note on Measurement of Utility, Review of Economic Studies, 1937；对照 Strotz, Review of Economic Studies, 1955–56</footer></div><p><a href="/econ/to-limit-order-book">上一课</a>（到限价簿：理论在此停）。主干在限价簿交接处停：均衡给出应当满足的 \\(p\\)，协议从队列处起，量化栏拥有<a href="/quant/lob-structure">限价簿</a>。本课是补层，不重写簿，也不把中间价当成欧拉里的 \\(r\\)。缺口是：主干已经用过 \\(\\beta\\)，但没有问这串权重为什么必须是几何的。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/two-period-micro">两期消费</a>把菜单写成 \\(u(c_0)+\\beta u(c_1)\\)；<a href="/econ/consumption-euler">跨期欧拉</a>把它沿无限期写下去。\\(\\beta\\) 从哪来？若只是「人更看重今天」，任意递减序列 \\(d_t\\) 都能加权。Samuelson（1937）的贴现效用把 \\(d_t=\\beta^t\\)，于是</p> \\[U_t=\\sum_{k=0}^{\\infty}\\beta^k u(c_{t+k}). \\]<p>缺口不是再推 <a href="/econ/expected-utility">vNM</a>，也不是再写斯勒茨基：确定消费上的排序已经有了。缺口是跨期加总的<strong>形状</strong>。任意 \\(d_t\\) 一般会时间不一致：在 \\(t\\) 订的 \\((c_{t+1},c_{t+2},\\ldots)\\)，到 \\(t+1\\) 用新的 \\(U_{t+1}\\) 会想改。指数贴现是使「今天的续计划 = 明天的最优」的充分条件。Strotz 把不一致写成动态的自我博弈；本课先钉住一致的那一支。</p><p><span class="marginnote">Koopmans（1960）把平稳性写成公理：推迟同样长的一段时间，相对排序不变。几何 \\(\\beta^t\\) 是平稳加可分的表示，不是对耐心的测量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象仍是日期商品上的偏好，见<a href="/econ/preference-choice">偏好</a>。补的只是可分加平稳：各期 \\(u\\) 相同，贴现因子对延迟长度不变。一阶条件沿用已有欧拉 \\(u&#39;(c_t)=\\beta(1+r_t)u&#39;(c_{t+1})\\)，不重导。时间一致的操作含义：在 \\(t\\) 选出的路径，限制在 \\(t+1\\) 的续路径上仍最大化 \\(U_{t+1}\\)。动态规划的贝尔曼方程依赖这一条；否则「值函数」每期要换一套偏好。</p>',10)),(a(),s(E,null,{default:o(()=>[d(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20STOP%5B%22%E4%B8%BB%E5%B9%B2%E5%81%9C%E5%9C%A8%E9%99%90%E4%BB%B7%E7%B0%BF%E4%BA%A4%E6%8E%A5%22%5D%20--%3E%20SUP%5B%22%E8%A1%A5%E5%B1%82%3A%20%E8%B7%A8%E6%9C%9F%E5%8A%A0%E6%80%BB%E7%9A%84%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20SUP%20--%3E%20EXP%5B%22%E6%8C%87%E6%95%B0%3A%20d_t%20%3D%20beta%5Et%22%5D%0A%20%20EXP%20--%3E%20TC%5B%22%E6%97%B6%E9%97%B4%E4%B8%80%E8%87%B4%3A%20%E7%BB%AD%E8%AE%A1%E5%88%92%E4%BB%8D%E6%9C%80%E4%BC%98%22%5D%0A%20%20TC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%8F%8C%E6%9B%B2%E6%8A%8A%E4%B8%80%E8%87%B4%E6%8B%86%E6%8E%89%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>市场利率 \\(r\\) 仍是相对价格，不是报价档。本课不进入簿。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>几何级数使相邻两期的相对权重永远是 \\(\\beta\\)，与「还剩多远」无关。因此自我之间没有冲突：未来的你用同一把尺。这与宏观政策课的时间不一致不是同一对象——那里是政府面对私人预期再优化；这里是同一偏好在不同日期是否还承认自己昨天的计划。补层回到家庭，不改 Kydland–Prescott 的政策故事。</p><p>指数贴现并不声称人真按 \\(\\beta^t\\) 感受延迟。它是使欧拉可递推、使生命周期计划可执行的技术。经验上短期贴现往往陡于长期，那是下一课的缺口。本课只要：主干里用过的 \\(\\beta\\)，在补层里被标明为时间一致的选择，而不是心理学常数。</p><p><a href="/econ/expected-utility">期望效用</a>管的是状态之间的加总，本课管的是日期之间的加总；两者都可分，独立性与几何贴现不是同一条公理。后课准双曲只拆日期权重，不拆 vNM。也不把 \\(r\\) 写成盘口利率。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重写 <a href="/econ/emh">EMH</a>、不重写股权溢价。不确定仍用已有期望效用，贴现与风险厌恶是两件事。也不把 \\(\\beta=1/(1+r)\\) 写成公理：那是切点，不是定义。无限期、连续时间只改求和为积分，形状仍是指数。</p><p>后课默认：说到「标准贴现效用」，指指数、时间一致；若要现时偏差，必须显式换权重。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主干在限价簿交接处停；本课是补层，回到跨期偏好，不重写簿。</li><li>Samuelson 贴现效用取几何权重，使计划时间一致。</li><li>\\(\\beta\\) 是偏好，\\(r\\) 是价格；欧拉在切点对齐，不重导。</li><li>非几何贴现把自我博弈留给下一课。</li><li>出处：Samuelson, <em>RES</em> 1937；Strotz, <em>RES</em> 1955–56；Koopmans 1960。</li></ul>',10))])}const S=n(p,[["render",_]]);export{b as __pageData,S as default};
